def calculate_pv(fv, r, n):
    pv = fv / (1 + r)**n
    return pv
def calculate_fv(pv, r, n):
    fv = pv * (1 + r)**n
    return fv

def calculate_bond_yield(face_value, coupon_rate, market_price):
    yield_rate = (face_value * coupon_rate / 100) / market_price
    return yield_rate

def calculate_twr(returns):
    twr = 1
    for ret in returns:
        twr *= (1 + ret)
    return twr - 1

def calculate_stcg(selling_price, cost_price):
  return selling_price - cost_price
def calculate_ltcg(selling_price, indexed_cost_price):
  return selling_price - indexed_cost_price

import math
def calculate_npvcashflows(cashflows, discount_rate):
    npv = 0
    for i, cashflow in enumerate(cashflows):
        npv += cashflow / (1 + discount_rate) ** (i + 1)
    return npv
